-- Local seed (spec §9): 3 events, 40 people mixing umich and gmail addresses,
-- two of them a deliberate ambiguous match, 5 V1 members, and the admin row.
--
-- Generated by `pnpm seed:generate` (scripts/generate-seed.ts) and committed as
-- static SQL so `supabase db reset` is deterministic. Edit the generator, not this.
--
-- SEED_ADMIN_EMAIL is read from the `app.seed_admin_email` GUC, never hardcoded.
-- Supply it once per local database, before `supabase db reset`:
--   psql "$SUPABASE_DB_URL" -c \
--     "alter database postgres set app.seed_admin_email = '$SEED_ADMIN_EMAIL'"
-- Without it the placeholder below is used, and no real account can sign in.



-- email_normalized is filled by the trigger in 0009.

-- Attendance, so the counts in the views are not all zero.

  coalesce(nullif(current_setting('app.seed_admin_email', true), ''), 'seed-admin@umich.edu')::citext,
  'admin', null)
on conflict (email) do update set role = 'admin';
